class Combinable(object):
    """
    Provides the ability to combine one or two objects with
    some connector. For example F('foo') + F('bar').
    """

    # Arithmetic connectors
    ADD = '+'
    SUB = '-'
    MUL = '*'
    DIV = '/'
    POW = '^'
    # The following is a quoted % operator - it is quoted because it can be
    # used in strings that also have parameter substitution.
    MOD = '%%'

    # Bitwise operators - note that these are generated by .bitand()
    # and .bitor(), the '&' and '|' are reserved for boolean operator
    # usage.
    BITAND = '&'
    BITOR = '|'
    BITLEFTSHIFT = '<<'
    BITRIGHTSHIFT = '>>'

    def _combine(self, other, connector, reversed, node=None):
        if not hasattr(other, 'resolve_expression'):
            # everything must be resolvable to an expression
            if isinstance(other, datetime.timedelta):
                other = DurationValue(other, output_field=fields.DurationField())
            else:
                other = Value(other)

        if reversed:
            return CombinedExpression(other, connector, self)
        return CombinedExpression(self, connector, other)

    def _perform_bitwise_operation(self, other, connector):
        """Perform a bitwise operation."""
        return self._combine(other, connector, False)

    def bitwise_and(self, other):
        """Perform a bitwise AND operation."""
        return self._perform_bitwise_operation(other, self.BITAND)

    def bitwise_or(self, other):
        """Perform a bitwise OR operation."""
        return self._perform_bitwise_operation(other, self.BITOR)

    def bitwise_left_shift(self, other):
        """Perform a bitwise left shift operation."""
        return self._combine(other, self.BITLEFTSHIFT, False)

    def bitwise_right_shift(self, other):
        """Perform a bitwise right shift operation."""
        return self._combine(other, self.BITRIGHTSHIFT, False)

    # ... rest of the class remains the same ...